import os
import numpy as np
import pandas as pd
import joblib
from tensorflow.keras.models import load_model

# --- 1. Robust File Detector & Loader for CMIP6 ---
print("Searching and loading CMIP6 files...")
gee_path = '/content/drive/MyDrive/GEE'
if not os.path.exists(gee_path):
    gee_path = '/content/drive/MyDrive'

files_in_dir = os.listdir(gee_path)
print(f"Scanning directory: {gee_path}")

def find_matching_file(pattern_list):
    for f in files_in_dir:
        if all(pat.lower() in f.lower() for pat in pattern_list) and f.endswith('.csv'):
            return os.path.join(gee_path, f)
    return None

# Attempt to locate each target scenario and period dataset
paths = {
    'ssp585_Near': find_matching_file(['CanESM5', 'ssp585', 'Near']),
    'ssp585_Mid': find_matching_file(['CanESM5', 'ssp585', 'Mid']),
    'ssp245_Near': find_matching_file(['CanESM5', 'ssp245', 'Near']),
    'ssp245_Mid': find_matching_file(['CanESM5', 'ssp245', 'Mid'])
}

future_dfs = []
for key, filepath in paths.items():
    if filepath and os.path.exists(filepath):
        print(f"  Found dataset: {os.path.basename(filepath)}")
        df = pd.read_csv(filepath)
        parts = key.split('_')
        df['scenario'] = parts[0]
        df['period'] = parts[1]
        future_dfs.append(df)
    else:
        print(f"  WARNING: Could not find matching CSV file for pattern: {key.replace('_', ' ')}")

if len(future_dfs) == 0:
    raise FileNotFoundError("None of the required CMIP6 CSV files could be located in Google Drive. Please verify files are present.")

# Concatenate and normalize columns
future_climate_df = pd.concat(future_dfs, ignore_index=True)
future_climate_df['date'] = pd.to_datetime(future_climate_df['date'], errors='coerce')
future_climate_df.dropna(subset=['date'], inplace=True)

# Rename standard variables to match training
column_rename_map = {
    'p_mm': 'avg_pcp',
    'tmin_c': 'avg_tmin',
    'tmax_c': 'avg_tmax'
}
future_climate_df.rename(columns=column_rename_map, inplace=True)
future_climate_df = future_climate_df.sort_values(by=['scenario', 'period', 'date']).reset_index(drop=True)
print(f"Future climate projections loaded. Total shape: {future_climate_df.shape}")

# --- 2. Feature Engineering ---
df_future_ml = future_climate_df.copy()
df_future_ml['year'] = df_future_ml['date'].dt.year
df_future_ml['month'] = df_future_ml['date'].dt.month
df_future_ml['day_of_year'] = df_future_ml['date'].dt.dayofyear
df_future_ml['day_of_week'] = df_future_ml['date'].dt.dayofweek
df_future_ml['week_of_year'] = df_future_ml['date'].dt.isocalendar().week.astype(int)

df_future_ml['rolling_avg_pcp_7d'] = df_future_ml.groupby(['scenario', 'period'])['avg_pcp'].transform(lambda x: x.rolling(window=7, min_periods=1).mean())

df_future_ml['Q_Simulated'] = np.nan
df_future_ml['observed_flow_lag1'] = np.nan
df_future_ml['simulated_flow_lag1'] = np.nan
df_future_ml['avg_pcp_lag1'] = df_future_ml.groupby(['scenario', 'period'])['avg_pcp'].transform(lambda x: x.shift(1))
df_future_ml['observed_flow_lag7'] = np.nan
df_future_ml['avg_pcp_lag7'] = df_future_ml.groupby(['scenario', 'period'])['avg_pcp'].transform(lambda x: x.shift(7))
df_future_ml['rolling_avg_observed_flow_7d'] = np.nan

# Drop NaN values due to lagging operations
df_future_ml.dropna(subset=['avg_pcp_lag1', 'avg_pcp_lag7', 'rolling_avg_pcp_7d'], inplace=True)
df_future_predictions = df_future_ml.copy()
print("Future climate features successfully engineered!")

# --- 3. Dynamic Recursive Forecasting ---
print("Starting recursive sequential forecasts...")

ml_features = [
    'Q_Simulated', 'avg_pcp', 'avg_tmax', 'avg_tmin', 'avg_slr', 'avg_wnd', 'avg_hmd',
    'observed_flow_lag1', 'simulated_flow_lag1', 'avg_pcp_lag1',
    'observed_flow_lag7', 'avg_pcp_lag7',
    'year', 'month', 'day_of_year', 'day_of_week', 'week_of_year',
    'rolling_avg_pcp_7d', 'rolling_avg_observed_flow_7d'
]

# Assumption constants mapped from historical averages
mean_avg_slr = 18.0
mean_avg_wnd = 2.0
mean_avg_hmd = 0.6

df_future_predictions['avg_slr'] = mean_avg_slr
df_future_predictions['avg_wnd'] = mean_avg_wnd
df_future_predictions['avg_hmd'] = mean_avg_hmd
historical_simulated_flow_mean = 92.1

df_future_predictions['RF_predictions'] = np.nan
df_future_predictions['XGB_predictions'] = np.nan
df_future_predictions['LightGBM_predictions'] = np.nan
df_future_predictions['LSTM_predictions'] = np.nan
df_future_predictions['Hybrid_predictions'] = np.nan

grouped_future_data = df_future_predictions.groupby(['scenario', 'period'])
all_forecast_groups = []

for (scenario, period), group_df in grouped_future_data:
    print(f"  Simulating scenario: {scenario} ({period})")
    group_preds = group_df.copy()
    group_preds['Q_Simulated'] = historical_simulated_flow_mean

    current_obs_lag1 = 33.6
    current_sim_lag1 = historical_simulated_flow_mean
    rolling_obs_window = [33.6] * 7

    for idx, row in group_df.iterrows():
        X_day = row.copy()
        X_day['Q_Simulated'] = historical_simulated_flow_mean
        X_day['observed_flow_lag1'] = current_obs_lag1
        X_day['simulated_flow_lag1'] = current_sim_lag1
        X_day['observed_flow_lag7'] = rolling_obs_window[-7]
        X_day['rolling_avg_observed_flow_7d'] = np.mean(rolling_obs_window[-7:])

        X_day_df = pd.DataFrame([X_day[ml_features].values], columns=ml_features)

        rf_p = max(0, rf_model.predict(X_day_df)[0])
        xgb_p = max(0, xgb_model.predict(X_day_df)[0])
        lgbm_p = max(0, lgbm_model.predict(X_day_df)[0])

        scaled_day = scaler.transform(X_day_df)
        lstm_p = max(0, lstm_model.predict(scaled_day.reshape(1, 1, scaled_day.shape[1]), verbose=0)[0][0])

        group_preds.loc[idx, 'RF_predictions'] = rf_p
        group_preds.loc[idx, 'XGB_predictions'] = xgb_p
        group_preds.loc[idx, 'LightGBM_predictions'] = lgbm_p
        group_preds.loc[idx, 'LSTM_predictions'] = lstm_p

        # Update state
        current_obs_lag1 = rf_p
        rolling_obs_window.append(rf_p)
        if len(rolling_obs_window) > 7:
            rolling_obs_window.pop(0)

    # Apply stacking model
    X_meta = pd.DataFrame({
        'RF_Pred': group_preds['RF_predictions'].values,
        'XGB_Pred': group_preds['XGB_predictions'].values,
        'LightGBM_Pred': group_preds['LightGBM_predictions'].values,
        'LSTM_Pred': group_preds['LSTM_predictions'].values
    })

    group_preds['Hybrid_predictions'] = np.maximum(0, hybrid_meta.predict(X_meta))
    all_forecast_groups.append(group_preds)

final_future_predictions_df = pd.concat(all_forecast_groups, ignore_index=True)
output_csv = os.path.join('/content/drive/MyDrive', 'future_streamflow_projections_CMIP6_stacking.csv')
final_future_predictions_df.to_csv(output_csv, index=False)
print(f"All predictions generated successfully! Saved to: {output_csv}")

