import numpy as np
from sklearn.metrics import r2_score, mean_squared_error

# Define NSE (Nash-Sutcliffe Efficiency) function
def calculate_nse(observed, simulated):
    numerator = np.sum((observed - simulated)**2)
    denominator = np.sum((observed - np.mean(observed))**2)
    if denominator == 0:
        return np.nan # Avoid division by zero
    return 1 - (numerator / denominator)

# Define PBIAS (Percent Bias) function
def calculate_pbias(observed, simulated):
    numerator = np.sum(simulated - observed)
    denominator = np.sum(observed)
    if denominator == 0:
        return np.nan # Avoid division by zero
    return (numerator / denominator) * 100

# --- Prepare Data for Merging ---
# Remove rows with NaT dates from OBSERVATION_DATA before merging
OBSERVATION_DATA_cleaned = OBSERVATION_DATA.dropna(subset=['Date']).copy()

# Rename columns for clarity before merging
# Correcting the column name for QSWATPLUS_SIMULATED_STREAMFLOW
QSWATPLUS_SIMULATED_STREAMFLOW_renamed = QSWATPLUS_SIMULATED_STREAMFLOW.rename(columns={'QSIMULATED': 'simulated_flow'}) # Ensure this is 'Q_Simulated' from Q_out.csv
OBSERVATION_DATA_renamed = OBSERVATION_DATA_cleaned.rename(columns={'observed-Flow': 'observed_flow'})

# Merge on Date, keeping only common dates
merged_flow_data = pd.merge(QSWATPLUS_SIMULATED_STREAMFLOW_renamed, OBSERVATION_DATA_renamed, on='Date', how='inner')

print("--- Head of Merged Observed and Simulated Flow Data ---")
display(merged_flow_data.head())

