import pandas as pd
import os

# Ensure merged_flow_pcp_data is defined
if 'merged_flow_pcp_data' not in locals() and 'merged_flow_pcp_data' not in globals():
    print("Warning: 'merged_flow_pcp_data' not found. Attempting to load from saved CSV.")
    drive_path = '/content/drive/MyDrive/' # Assuming drive_path is defined elsewhere, or explicitly set here.
    output_file_path = os.path.join(drive_path, 'merged_flow_precipitation_data.csv')
    try:
        merged_flow_pcp_data = pd.read_csv(output_file_path)
        merged_flow_pcp_data['Date'] = pd.to_datetime(merged_flow_pcp_data['Date'])
        print(f"Successfully loaded 'merged_flow_pcp_data' from {output_file_path}")
    except FileNotFoundError:
        print(f"Error: 'merged_flow_precipitation_data.csv' not found at {output_file_path}. Please ensure the data merging cell has been executed to create and save this file.")
        raise NameError("Required DataFrame 'merged_flow_pcp_data' is not defined and could not be loaded.")
    except Exception as e:
        print(f"An error occurred while loading 'merged_flow_pcp_data': {e}")
        raise

# Create a copy of the merged data for feature engineering
df_ml = merged_flow_pcp_data.copy()

# Sort by date to ensure correct lagging
df_ml = df_ml.sort_values(by='Date').reset_index(drop=True)

# --- Create Lagged Features ---
# Lagged observed flow (previous day's observed flow)
df_ml['observed_flow_lag1'] = df_ml['observed_flow'].shift(1)
# Lagged simulated flow (previous day's simulated flow)
df_ml['simulated_flow_lag1'] = df_ml['Q_Simulated'].shift(1)
# Lagged average precipitation (previous day's avg_pcp)
df_ml['avg_pcp_lag1'] = df_ml['avg_pcp'].shift(1)

# You can add more lags as needed, e.g., for weekly patterns
df_ml['observed_flow_lag7'] = df_ml['observed_flow'].shift(7)
df_ml['avg_pcp_lag7'] = df_ml['avg_pcp'].shift(7)

# --- Create Time-based Features ---
df_ml['year'] = df_ml['Date'].dt.year
df_ml['month'] = df_ml['Date'].dt.month
df_ml['day_of_year'] = df_ml['Date'].dt.dayofyear
df_ml['day_of_week'] = df_ml['Date'].dt.dayofweek # Monday=0, Sunday=6
df_ml['week_of_year'] = df_ml['Date'].dt.isocalendar().week.astype(int)

# --- Create Rolling Window Statistics ---
# 7-day rolling mean of average precipitation
df_ml['rolling_avg_pcp_7d'] = df_ml['avg_pcp'].rolling(window=7).mean()
# 7-day rolling mean of observed flow
df_ml['rolling_avg_observed_flow_7d'] = df_ml['observed_flow'].rolling(window=7).mean()

# Drop rows with NaN values resulting from lagging/rolling operations
df_ml = df_ml.dropna().reset_index(drop=True)

print("--- Head of DataFrame with new features ---")
display(df_ml.head())
print("\n--- Info of DataFrame with new features ---")
df_ml.info()

import pandas as pd

# Define features (X) and target (y)
# We will try to predict 'observed_flow' using the engineered features
features = [
    'Q_Simulated', 'avg_pcp', 'avg_tmax', 'avg_tmin', 'avg_slr', 'avg_wnd', 'avg_hmd',
    'observed_flow_lag1', 'simulated_flow_lag1', 'avg_pcp_lag1',
    'observed_flow_lag7', 'avg_pcp_lag7',
    'year', 'month', 'day_of_year', 'day_of_week', 'week_of_year',
    'rolling_avg_pcp_7d', 'rolling_avg_observed_flow_7d'
]
target = 'observed_flow'

X = df_ml[features]
y = df_ml[target]

# Filter the data based on the previously defined periods
# Ensure the date column for filtering matches the df_ml's 'Date' column type
calibration_start = pd.to_datetime('1988-01-01')
calibration_end = pd.to_datetime('2002-12-31')
