# Training data (Calibration period)
X_train = X[(df_ml['Date'] >= calibration_start) & (df_ml['Date'] <= calibration_end)]
y_train = y[(df_ml['Date'] >= calibration_start) & (df_ml['Date'] <= calibration_end)]

# Testing data (Validation period)
X_test = X[(df_ml['Date'] >= validation_start) & (df_ml['Date'] <= validation_end)]
y_test = y[(df_ml['Date'] >= validation_start) & (df_ml['Date'] <= validation_end)]

