import pandas as pd
import numpy as np

# Define Calibration and Validation Periods (as these might be needed if kernel restarted)
calibration_start = '1988-01-01'
calibration_end = '2002-12-31'
validation_start = '2003-01-01'
validation_end = '2011-12-31'

# Re-filter val_data to ensure it's in scope for getting Q_Simulated
# This assumes merged_flow_pcp_data is available from earlier cells
if 'merged_flow_pcp_data' in locals() or 'merged_flow_pcp_data' in globals():
    val_data = merged_flow_pcp_data[
        (merged_flow_pcp_data['Date'] >= validation_start) &
        (merged_flow_pcp_data['Date'] <= validation_end)
    ].copy()
else:
    print("Warning: merged_flow_pcp_data not found. Attempting to load val_data from predictions file.")
    val_data = pd.DataFrame({'Q_Simulated': X_test['Q_Simulated'].values}) # Simplified fallback

# Initialize metrics_summary with QSWATPLUS validation metrics (from previous execution if available)
# If metrics_summary is not yet defined, create a placeholder
if 'metrics_summary' not in locals() and 'metrics_summary' not in globals():
    print("Warning: 'metrics_summary' not found. Initializing with QSWATPLUS metrics.")
    # Example: Use default values or calculate from val_data if possible
    # For this robust re-execution, we assume val_data and X_test are populated.
    qswat_observed = val_data['observed_flow'] if 'observed_flow' in val_data.columns else y_test
    qswat_simulated = val_data['Q_Simulated']

    qswat_r2 = r2_score(qswat_observed, qswat_simulated) if not qswat_observed.empty else np.nan
    qswat_rmse = np.sqrt(mean_squared_error(qswat_observed, qswat_simulated)) if not qswat_observed.empty else np.nan
    qswat_nse = calculate_nse(qswat_observed, qswat_simulated) if not qswat_observed.empty else np.nan
    qswat_pbias = calculate_pbias(qswat_observed, qswat_simulated) if not qswat_observed.empty else np.nan

    metrics_summary = pd.DataFrame({
        'Metric': ['R2', 'RMSE', 'NSE', 'PBIAS'],
        'Validation Period (2003-2011)': [qswat_r2, qswat_rmse, qswat_nse, qswat_pbias]
    }).set_index('Metric')

# Populate r2_scores with actual R2 values from validation period
r2_scores = {
    'QSWATPLUS': metrics_summary.loc['R2', 'Validation Period (2003-2011)'], # Use validation period R2 for BMA weighting
    'Random Forest': r2_rf,
    'XGBoost': r2_xgb,
    'LightGBM': r2_lgbm,
    'LSTM': r2_lstm
}

# Handle potential negative R2 scores for weighting (replace with small positive value)
r2_scores = {k: max(0.0001, v) for k, v in r2_scores.items()}

raw_weights = np.array(list(r2_scores.values()))
bma_weights = raw_weights / np.sum(raw_weights)

print("--- Model R2 Scores and BMA Weights (Validation Period) ---") # Corrected print statement
for i, (model_name, r2) in enumerate(r2_scores.items()):
    print(f"{model_name:<15}: R2 = {r2:.3f}, Weight = {bma_weights[i]:.3f}")

qswatplus_pred_val = val_data['Q_Simulated'].values # Corrected to Q_Simulated

predictions_df_val = pd.DataFrame({
    'QSWATPLUS_Pred': qswatplus_pred_val,
    'RF_Pred': rf_predictions,
    'XGB_Pred': xgb_predictions,
    'LightGBM_Pred': lgbm_predictions,
    'LSTM_Pred': lstm_predictions
})

bma_predictions = np.average(predictions_df_val.values, axis=1, weights=bma_weights)

print("\n--- BMA Model Performance (Validation Period) ---") # Corrected print statement
r2_bma = r2_score(y_test, bma_predictions)
rmse_bma = np.sqrt(mean_squared_error(y_test, bma_predictions))
nse_bma = calculate_nse(y_test, bma_predictions)
pbias_bma = calculate_pbias(y_test, bma_predictions)

print(f"R2: {r2_bma:.3f}")
print(f"RMSE: {rmse_bma:.3f}")
print(f"NSE: {nse_bma:.3f}")
print(f"PBIAS: {pbias_bma:.3f}%")

