import pandas as pd
import numpy as np
from scipy.stats import shapiro, skew, kurtosis, kstest, norm
import matplotlib.pyplot as plt
import seaborn as sns
import os

drive_path = '/content/drive/MyDrive/'
output_file_path_cal = os.path.join(drive_path, 'model_predictions_calibration_period.csv')

# Load the calibration predictions DataFrame
try:
    calibration_predictions_df = pd.read_csv(output_file_path_cal)
    calibration_predictions_df['Date'] = pd.to_datetime(calibration_predictions_df['Date'])
    print(f"Successfully loaded calibration predictions from: {output_file_path_cal}")
except FileNotFoundError:
    print(f"Error: 'model_predictions_calibration_period.csv' not found at {output_file_path_cal}.")
    print("Please ensure the cell that generates and saves this file (e.g., cell 3ed40035) has been executed.")
    calibration_predictions_df = pd.DataFrame() # Create an empty DataFrame to avoid further errors
except Exception as e:
    print(f"An error occurred while loading calibration predictions: {e}")
    calibration_predictions_df = pd.DataFrame()

if not calibration_predictions_df.empty:
    # Calculate residuals for each model
    calibration_residuals = {}
    models_to_analyze = [
        'QSWATPLUS Predictions',
        'RF Predictions',
        'XGB Predictions',
        'LightGBM Predictions',
        'LSTM Predictions',
        'Overall Hybrid Predictions',
        'BMA Predictions',
        'Hybrid_QSWATPLUS_RF Predictions',
        'Hybrid_QSWATPLUS_XGB Predictions',
        'Hybrid_QSWATPLUS_LGBM Predictions',
        'Hybrid_QSWATPLUS_LSTM Predictions'
    ]

    for col in models_to_analyze:
        if col in calibration_predictions_df.columns:
            residuals = calibration_predictions_df['Observed Flow'] - calibration_predictions_df[col]
            calibration_residuals[col.replace(' Predictions', '') + ' Residuals'] = residuals
        else:
            print(f"Warning: Column '{col}' not found in calibration_predictions_df. Skipping residuals calculation for this model.")

    # --- Perform Shapiro-Wilk Normality Test ---
    print("\n--- Shapiro-Wilk Normality Test Results (Calibration Period Residuals) ---")
    shapiro_results_cal = {}
    for model_name, residuals_series in calibration_residuals.items():
        if len(residuals_series) >= 3 and len(residuals_series) <= 5000: # Shapiro-Wilk limit
            stat, p = shapiro(residuals_series)
            shapiro_results_cal[model_name] = {'W-statistic': stat, 'p-value': p}
            print(f"\n{model_name}:")
            print(f"  W-statistic = {stat:.4f}")
            print(f"  p-value = {p:.4f}")
            if p < 0.05:
                print(f"  Residuals are likely NOT normally distributed (reject H0).")
            else:
                print(f"  Residuals appear normally distributed (fail to reject H0).")
        else:
            print(f"Warning: Skipping Shapiro-Wilk for {model_name} due to sample size ({len(residuals_series)}). Must be between 3 and 5000.")

    shapiro_df_cal = pd.DataFrame.from_dict(shapiro_results_cal, orient='index')
    shapiro_df_cal.index.name = 'Model'
    print("\n--- Summary of Shapiro-Wilk Test Results (Calibration Period) ---")
    display(shapiro_df_cal.round(4))

    # --- Skewness and Kurtosis of Residuals ---
    print("\n--- Skewness and Kurtosis of Residuals (Calibration Period) ---")
    skewness_results_cal = {}
    kurtosis_results_cal = {}

    for model_name, residuals_series in calibration_residuals.items():
        model_skew = skew(residuals_series)
        model_kurtosis = kurtosis(residuals_series) # Default scipy calculates excess kurtosis

        skewness_results_cal[model_name] = model_skew
        kurtosis_results_cal[model_name] = model_kurtosis

        print(f"\n{model_name}:")
        print(f"  Skewness = {model_skew:.4f}")
        print(f"  Kurtosis (Excess) = {model_kurtosis:.4f}")

    skew_kurt_df_cal = pd.DataFrame({'Skewness': skewness_results_cal, 'Kurtosis (Excess)': kurtosis_results_cal})
    skew_kurt_df_cal.index.name = 'Model'
    print("\n--- Summary of Skewness and Kurtosis Results (Calibration Period) ---")
    display(skew_kurt_df_cal.round(4))

    # --- Kolmogorov-Smirnov D-statistic ---
    print("\n--- Kolmogorov-Smirnov D-statistic (Calibration Period Residuals) ---")
    ks_results_cal = {}

    for model_name, residuals_series in calibration_residuals.items():
        mean_res = np.mean(residuals_series)
        std_res = np.std(residuals_series)
        stat_ks, p_ks = kstest(residuals_series, 'norm', args=(mean_res, std_res))
        ks_results_cal[model_name] = {'KS-D Statistic': stat_ks, 'p-value': p_ks}
        print(f"\n{model_name}:")
        print(f"  KS-D Statistic = {stat_ks:.4f}")
        print(f"  p-value = {p_ks:.4f}")
        if p_ks < 0.05:
            print(f"  Residuals are likely NOT normally distributed (reject H0).")
        else:
            print(f"  Residuals appear normally distributed (fail to reject H0).")

    ks_df_cal = pd.DataFrame.from_dict(ks_results_cal, orient='index')
    ks_df_cal.index.name = 'Model'
    print("\n--- Summary of Kolmogorov-Smirnov Test Results (Calibration Period) ---")
    display(ks_df_cal.round(4))

    # --- Visualize Residuals: Histograms ---
    print("\n--- Visualizing Residuals (Calibration Period) ---")
    # Assuming 'QSWATPLUS Residuals' and 'Overall Hybrid Residuals' are keys in calibration_residuals
    if 'QSWATPLUS Residuals' in calibration_residuals and 'Overall Hybrid Residuals' in calibration_residuals:
        fig, axes = plt.subplots(1, 2, figsize=(16, 6))
        fig.suptitle('Distribution of Residuals (Calibration Period)', fontsize=16)

        sns.histplot(calibration_residuals['QSWATPLUS Residuals'], kde=True, color='skyblue', ax=axes[0])
        axes[0].set_title('QSWATPLUS Residuals')
        axes[0].set_xlabel('Residuals (m^3/s)')
        axes[0].set_ylabel('Frequency')
        axes[0].grid(True)

        sns.histplot(calibration_residuals['Overall Hybrid Residuals'], kde=True, color='lightgreen', ax=axes[1])
        axes[1].set_title('Overall Hybrid Model Residuals')
        axes[1].set_xlabel('Residuals (m^3/s)')
        axes[1].set_ylabel('Frequency')
        axes[1].grid(True)

        plt.tight_layout(rect=[0, 0.03, 1, 0.95])
        plt.show()
    else:
        print("Cannot plot histograms: QSWATPLUS and/or Overall Hybrid Residuals not found.")

    # --- Visualize Residuals: Time Series ---
    if 'QSWATPLUS Residuals' in calibration_residuals and 'Overall Hybrid Residuals' in calibration_residuals:
        fig, axes = plt.subplots(2, 1, figsize=(18, 10), sharex=True)
        fig.suptitle('Residuals Over Time (Calibration Period)', fontsize=16)

        sns.lineplot(ax=axes[0], x=calibration_predictions_df['Date'], y=calibration_residuals['QSWATPLUS Residuals'], color='purple', alpha=0.7)
        axes[0].axhline(0, color='red', linestyle='--', linewidth=1.5, label='Zero Residuals')
        axes[0].set_title('QSWATPLUS Residuals Over Time')
        axes[0].set_ylabel('Residuals (m^3/s)')
        axes[0].legend()
        axes[0].grid(True)

        sns.lineplot(ax=axes[1], x=calibration_predictions_df['Date'], y=calibration_residuals['Overall Hybrid Residuals'], color='green', alpha=0.7)
        axes[1].axhline(0, color='red', linestyle='--', linewidth=1.5, label='Zero Residuals')
        axes[1].set_title('Overall Hybrid Model Residuals Over Time')
        axes[1].set_xlabel('Date')
        axes[1].set_ylabel('Residuals (m^3/s)')
        axes[1].legend()
        axes[1].grid(True)

        plt.tight_layout(rect=[0, 0.03, 1, 0.95])
        plt.show()
    else:
        print("Cannot plot time series: QSWATPLUS and/or Overall Hybrid Residuals not found.")
else:
    print("Calibration predictions DataFrame is empty. Cannot perform residual and normality analysis.")

