import numpy as np
import glob, os

# Calculate daily average precipitation and other climate variables from all stations
daily_avg_climate = merged_data_with_stations.groupby('Date').agg(
    avg_pcp=('pcp', 'mean'),
    avg_tmax=('tmax', 'mean'),
    avg_tmin=('tmin', 'mean'),
    avg_slr=('slr', 'mean'),
    avg_wnd=('wnd', 'mean'),
    avg_hmd=('hmd', 'mean')
).reset_index()

# Merge this daily average climate data with the combined flow data
