print("\n--- Info for Merged Flow and Average Climate Data ---")
merged_flow_pcp_data.info()

# Create a copy of the merged data for feature engineering
df_ml = merged_flow_pcp_data.copy()

# Sort by date to ensure correct lagging
df_ml = df_ml.sort_values(by='Date').reset_index(drop=True)

# --- Create Lagged Features ---
# Lagged observed flow (previous day's observed flow)
df_ml['observed_flow_lag1'] = df_ml['observed_flow'].shift(1)
# Lagged simulated flow (previous day's simulated flow)
df_ml['simulated_flow_lag1'] = df_ml['Q_Simulated'].shift(1) # Corrected column name to Q_Simulated
# Lagged average precipitation (previous day's avg_pcp)
df_ml['avg_pcp_lag1'] = df_ml['avg_pcp'].shift(1)

# You can add more lags as needed, e.g., for weekly patterns
df_ml['observed_flow_lag7'] = df_ml['observed_flow'].shift(7)
df_ml['avg_pcp_lag7'] = df_ml['avg_pcp'].shift(7)

# --- Create Time-based Features ---
df_ml['year'] = df_ml['Date'].dt.year
df_ml['month'] = df_ml['Date'].dt.month
df_ml['day_of_year'] = df_ml['Date'].dt.dayofyear
df_ml['day_of_week'] = df_ml['Date'].dt.dayofweek # Monday=0, Sunday=6
df_ml['week_of_year'] = df_ml['Date'].dt.isocalendar().week.astype(int)

# --- Create Rolling Window Statistics ---
# 7-day rolling mean of average precipitation
df_ml['rolling_avg_pcp_7d'] = df_ml['avg_pcp'].rolling(window=7).mean()
# 7-day rolling mean of observed flow
df_ml['rolling_avg_observed_flow_7d'] = df_ml['observed_flow'].rolling(window=7).mean()

# Drop rows with NaN values resulting from lagging/rolling operations
df_ml = df_ml.dropna().reset_index(drop=True)

print("--- Head of DataFrame with new features ---")
