# Convert precipitation from kg m-2 s-1 to mm/day
# (1 kg m-2 s-1 = 86400 mm/day, assuming water density of 1000 kg/m3)
combined_cmip6_data['avg_pcp'] = combined_cmip6_data['avg_pcp'] * 86400

# Convert temperatures from Kelvin to Celsius
combined_cmip6_data['avg_tmax'] = combined_cmip6_data['avg_tmax'] - 273.15
combined_cmip6_data['avg_tmin'] = combined_cmip6_data['avg_tmin'] - 273.15

# Group by Date, Period, and Scenario and calculate the mean for climate variables
ensemble_cmip6_df = combined_cmip6_data.groupby(['Date', 'Period', 'Scenario']).agg(
    avg_pcp=('avg_pcp', 'mean'),
    avg_tmax=('avg_tmax', 'mean'),
    avg_tmin=('avg_tmin', 'mean')
).reset_index()

# Sort by Date, Period, and Scenario for consistency
ensemble_cmip6_df = ensemble_cmip6_df.sort_values(by=['Scenario', 'Period', 'Date']).reset_index(drop=True)

