import pandas as pd
import numpy as np

# Create a copy of ensemble_cmip6_df to work with for feature engineering
df_future_ml = ensemble_cmip6_df.copy()

# Rename 'Date' column to 'date' for consistency with previous future climate data cells if applicable
df_future_ml.rename(columns={'Date': 'date'}, inplace=True)

# Sort by date for correct lagging operations
df_future_ml = df_future_ml.sort_values(by=['Scenario', 'Period', 'date']).reset_index(drop=True)

# --- Create Time-based Features ---
df_future_ml['year'] = df_future_ml['date'].dt.year
df_future_ml['month'] = df_future_ml['date'].dt.month
df_future_ml['day_of_year'] = df_future_ml['date'].dt.dayofyear
df_future_ml['day_of_week'] = df_future_ml['date'].dt.dayofweek # Monday=0, Sunday=6
df_future_ml['week_of_year'] = df_future_ml['date'].dt.isocalendar().week.astype(int)

# --- Create Cyclical Time-based Features ---
df_future_ml['doy_sin'] = np.sin(2 * np.pi * df_future_ml['day_of_year'] / 365.0)
df_future_ml['doy_cos'] = np.cos(2 * np.pi * df_future_ml['day_of_year'] / 365.0)

# --- Create Rolling Window Statistics ---
# Rolling window statistics need to be calculated carefully for each scenario/Period group
# to avoid data leakage across different future projections.
df_future_ml['rolling_avg_pcp_7d'] = df_future_ml.groupby(['Scenario', 'Period'])['avg_pcp'].transform(lambda x: x.rolling(window=7, min_periods=1).mean())

# --- Create Lagged Features (with placeholders for flow-related lags) ---
# Placeholder for QSWATPLUS simulated flow in the future
df_future_ml['simulated_flow'] = np.nan
# Placeholder for lagged observed flow (will be filled iteratively during prediction)
df_future_ml['observed_flow_lag1'] = np.nan
df_future_ml['simulated_flow_lag1'] = np.nan
# Lagged average precipitation
df_future_ml['avg_pcp_lag1'] = df_future_ml.groupby(['Scenario', 'Period'])['avg_pcp'].transform(lambda x: x.shift(1))
df_future_ml['observed_flow_lag7'] = np.nan
df_future_ml['avg_pcp_lag7'] = df_future_ml.groupby(['Scenario', 'Period'])['avg_pcp'].transform(lambda x: x.shift(7))
df_future_ml['rolling_avg_observed_flow_7d'] = np.nan

# Drop rows with NaN values resulting from initial lags for each group
# This might remove the first few days of each scenario/Period, which is expected for lagged features.
df_future_ml.dropna(subset=['avg_pcp_lag1', 'avg_pcp_lag7', 'rolling_avg_pcp_7d'], inplace=True)

print("--- Head of Feature-Engineered Future Climate Data ---")
display(df_future_ml.head())
print("\n--- Info of Feature-Engineered Future Climate Data ---")
df_future_ml.info()

print("--- Summary Statistics for ensemble_cmip6_df by Scenario ---")
for scenario, group_df in ensemble_cmip6_df.groupby('Scenario'):
    print(f"\nScenario: {scenario}")
    display(group_df[['avg_pcp', 'avg_tmax', 'avg_tmin']].describe().round(2))

column_rename_map = {
    'pr': 'avg_pcp',
    'tasmax': 'avg_tmax',
    'tasmin': 'avg_tmin'
}

# Apply the renaming to each DataFrame in the cmip6_daily_data dictionary
for model_name, df in cmip6_daily_data.items():
    # Only rename if the column exists to avoid KeyError for missing columns
    columns_to_rename = {old_name: new_name for old_name, new_name in column_rename_map.items() if old_name in df.columns}
    df.rename(columns=columns_to_rename, inplace=True)
    cmip6_daily_data[model_name] = df

print("Columns renamed in CMIP6 daily dataframes.")

# Display the head of one of the modified dataframes to verify
if cmip6_daily_data:
    first_model_name = next(iter(cmip6_daily_data))
    print(f"\nHead of '{first_model_name}' DataFrame after column renaming:")
    display(cmip6_daily_data[first_model_name].head())

