import numpy as np
from sklearn.metrics import r2_score, mean_squared_error
import pandas as pd # Needed for DataFrame operations
import os # Needed for os.path.join if loading from CSV

# Define NSE (Nash-Sutcliffe Efficiency) function
def calculate_nse(observed, simulated):
    numerator = np.sum((observed - simulated)**2)
    denominator = np.sum((observed - np.mean(observed))**2)
    if denominator == 0:
        return np.nan # Avoid division by zero
    return 1 - (numerator / denominator)

# Define PBIAS (Percent Bias) function
def calculate_pbias(observed, simulated):
    numerator = np.sum(simulated - observed)
    denominator = np.sum(observed)
    if denominator == 0:
        return np.nan # Avoid division by zero
    return (numerator / denominator) * 100

# Re-create cal_data and val_data if not in scope or if merged_flow_pcp_data is missing
if 'merged_flow_pcp_data' not in locals() and 'merged_flow_pcp_data' not in globals():
    print("Warning: 'merged_flow_pcp_data' not found. Attempting to load from saved CSV.")
    drive_path_root = '/content/drive/MyDrive/'
    try:
        merged_flow_pcp_data = pd.read_csv(os.path.join(drive_path_root, 'merged_flow_precipitation_data.csv'))
        merged_flow_pcp_data['Date'] = pd.to_datetime(merged_flow_pcp_data['Date'])
    except Exception as e:
        print(f"Error loading 'merged_flow_precipitation_data.csv': {e}")
        merged_flow_pcp_data = pd.DataFrame(columns=['Date', 'Q_Simulated', 'observed_flow']) # Empty DF
        cal_data = pd.DataFrame(columns=['Date', 'Q_Simulated', 'observed_flow'])
        val_data = pd.DataFrame(columns=['Date', 'Q_Simulated', 'observed_flow'])
else:
    # Define Calibration and Validation Periods
    calibration_start = '1988-01-01'
    calibration_end = '2002-12-31'
    validation_start = '2003-01-01'
    validation_end = '2011-12-31'

    # Filter data for calibration period
    cal_data = merged_flow_pcp_data[
        (merged_flow_pcp_data['Date'] >= calibration_start) &
        (merged_flow_pcp_data['Date'] <= calibration_end)
    ].copy()

    # Filter data for validation period
    val_data = merged_flow_pcp_data[
        (merged_flow_pcp_data['Date'] >= validation_start) &
        (merged_flow_pcp_data['Date'] <= validation_end)
    ].copy()

# --- Calculate Performance Metrics for Calibration Period ---
if not cal_data.empty:
    cal_observed = cal_data['observed_flow']
    cal_simulated = cal_data['Q_Simulated']

    r2_cal = r2_score(cal_observed, cal_simulated)
    rmse_cal = np.sqrt(mean_squared_error(cal_observed, cal_simulated))
    nse_cal = calculate_nse(cal_observed, cal_simulated)
    pbias_cal = calculate_pbias(cal_observed, cal_simulated)

    print("\n--- Performance Metrics (Calibration Period: 1988-2002) ---")
    print(f"R2: {r2_cal:.3f}")
    print(f"RMSE: {rmse_cal:.3f}")
    print(f"NSE: {nse_cal:.3f}")
    print(f"PBIAS: {pbias_cal:.3f}%")
else:
    print("\nNo data available for the Calibration Period.")
    # Initialize with NaN if data is missing
    r2_cal, rmse_cal, nse_cal, pbias_cal = np.nan, np.nan, np.nan, np.nan

# --- Calculate Performance Metrics for Validation Period ---
if not val_data.empty:
    val_observed = val_data['observed_flow']
    val_simulated = val_data['Q_Simulated']

    r2_val = r2_score(val_observed, val_simulated)
    rmse_val = np.sqrt(mean_squared_error(val_observed, val_simulated))
    nse_val = calculate_nse(val_observed, val_simulated)
    pbias_val = calculate_pbias(val_observed, val_simulated)

    print("\n--- Performance Metrics (Validation Period: 2003-2011) ---")
    print(f"R2: {r2_val:.3f}")
    print(f"RMSE: {rmse_val:.3f}")
    print(f"NSE: {nse_val:.3f}")
    print(f"PBIAS: {pbias_val:.3f}%")
else:
    print("\nNo data available for the Validation Period.")
    # Initialize with NaN if data is missing
    r2_val, rmse_val, nse_val, pbias_val = np.nan, np.nan, np.nan, np.nan

"""This cell calculates several performance metrics for the QSWATPLUS model for both the calibration and validation periods:

*   **R² (Coefficient of Determination):** Measures how well the simulated flow replicates the variability of the observed flow. A value close to 1 indicates a good fit.
*   **RMSE (Root Mean Square Error):** Quantifies the average magnitude of the errors between simulated and observed flow. Lower values indicate better accuracy.
*   **NSE (Nash-Sutcliffe Efficiency):** Indicates how well the plot of observed versus simulated flow fits the 1:1 line. Values range from -∞ to 1, with 1 being the optimal value (perfect fit).
*   **PBIAS (Percent Bias):** Measures the average tendency of the simulated data to be larger or smaller than their observed counterparts. Positive values indicate over-prediction, negative values indicate under-prediction, and values close to 0 are ideal.

### Time Series Plot: Monthly Average Observed vs. Simulated Flow

This plot visualizes the monthly average observed and simulated streamflow over the entire period (calibration and validation combined). This helps in understanding how well the model captures the long-term temporal dynamics and seasonal patterns of streamflow.
"""

