print("Shape of X_test_lstm:", X_test_lstm.shape)

"""#### Building and Training the LSTM Model

Now we'll define a simple LSTM model using TensorFlow/Keras, compile it, and train it on the prepared data. We'll then evaluate its performance on the test set.
"""

from tensorflow.keras.models import Sequential
from tensorflow.keras.layers import LSTM, Dense

# Define the LSTM model architecture
lstm_model = Sequential([
    LSTM(50, activation='relu', input_shape=(X_train_lstm.shape[1], X_train_lstm.shape[2])),
    Dense(1)
])

# Compile the model
lstm_model.compile(optimizer='adam', loss='mse')

# Display model summary
