# LSTM Residuals
lstm_residuals_val = plot_df['Observed Flow'] - plot_df['LSTM Predictions']

# --- Perform Shapiro-Wilk Test --- (Note: Shapiro-Wilk is sensitive to sample size; large N can lead to small p-values)

print("\n--- Shapiro-Wilk Normality Test Results (Validation Period Residuals) ---")

models = {
    'QSWATPLUS': qswatplus_residuals_val,
    'Random Forest': rf_residuals_val,
    'XGBoost': xgb_residuals_val,
    'LightGBM': lgbm_residuals_val,
    'LSTM': lstm_residuals_val
}

shapiro_results = {}

for model_name, residuals in models.items():
    # Shapiro-Wilk test has a sample size limit, often around 5000.
    # If the dataset is larger, we might take a sample or use other tests like Kolmogorov-Smirnov.
    # For now, we run on the full validation data, but be aware of this limitation.
    stat, p = shapiro(residuals)
    shapiro_results[model_name] = {'W-statistic': stat, 'p-value': p}
    print(f"\n{model_name}:")
    print(f"  W-statistic = {stat:.4f}")
    print(f"  p-value = {p:.4f}")
    if p < 0.05:
        print(f"  Residuals are likely NOT normally distributed (reject H0).")
    else:
        print(f"  Residuals appear normally distributed (fail to reject H0).")

# Display results in a DataFrame for better readability
shapiro_df = pd.DataFrame.from_dict(shapiro_results, orient='index')
shapiro_df.index.name = 'Model'
print("\n--- Summary of Shapiro-Wilk Test Results ---")
display(shapiro_df.round(4))

from scipy.stats import kstest, norm

print("\n--- Kolmogorov-Smirnov D-statistic (Validation Period Residuals) ---")

ks_results = {}

for model_name, residuals in models.items():
    # Calculate mean and standard deviation of the residuals
    mean_res = np.mean(residuals)
    std_res = np.std(residuals)

    # Perform one-sample Kolmogorov-Smirnov test against a normal distribution
    # The 'args' parameter passes the mean and std dev to the normal distribution function
    stat_ks, p_ks = kstest(residuals, 'norm', args=(mean_res, std_res))
    ks_results[model_name] = {'KS-D Statistic': stat_ks, 'p-value': p_ks}
    print(f"\n{model_name}:")
    print(f"  KS-D Statistic = {stat_ks:.4f}")
    print(f"  p-value = {p_ks:.4f}")
    if p_ks < 0.05:
        print(f"  Residuals are likely NOT normally distributed (reject H0).")
    else:
        print(f"  Residuals appear normally distributed (fail to reject H0).")

# Display results in a DataFrame for better readability
ks_df = pd.DataFrame.from_dict(ks_results, orient='index')
ks_df.index.name = 'Model'
print("\n--- Summary of Kolmogorov-Smirnov Test Results ---")
display(ks_df.round(4))

