import pandas as pd
import numpy as np # Import numpy for np.nan

# Define NSE (Nash-Sutcliffe Efficiency) function if not already defined
def calculate_nse(observed, simulated):
    numerator = np.sum((observed - simulated)**2)
    denominator = np.sum((observed - np.mean(observed))**2)
    if denominator == 0:
        return np.nan # Avoid division by zero
    return 1 - (numerator / denominator)

# Define PBIAS (Percent Bias) function if not already defined
def calculate_pbias(observed, simulated):
    numerator = np.sum(simulated - observed)
    denominator = np.sum(observed)
    if denominator == 0:
        return np.nan # Avoid division by zero
    return (numerator / denominator) * 100

# Helper function to get a metric, or np.nan if not defined
def get_metric(name):
    return globals().get(name, np.nan)

