"""### Statistical Significance of Performance Improvement (Paired t-test on Absolute Residuals)

To determine if the observed performance improvement of the Hybrid Model over the QSWATPLUS model is statistically significant, we can perform a paired t-test on their absolute residuals. The null hypothesis ($H_0$) is that there is no significant difference between the mean absolute residuals of the two models, while the alternative hypothesis ($H_1$) is that there is a significant difference (or that one is significantly lower).

Specifically, we want to test if the absolute residuals of the Hybrid Model are significantly *lower* than those of the QSWATPLUS model, which would indicate a statistically significant improvement in accuracy.
"""

from scipy import stats
import numpy as np
import pandas as pd
import os

drive_path = '/content/drive/MyDrive/'
output_file_path_final_all = os.path.join(drive_path, 'model_predictions_comparison_final.csv')

# Explicitly load full_predictions_df if not already present or is empty
if 'full_predictions_df' not in globals() or full_predictions_df.empty:
    try:
        full_predictions_df = pd.read_csv(output_file_path_final_all)
        full_predictions_df['Date'] = pd.to_datetime(full_predictions_df['Date'])
        print(f"Successfully loaded full_predictions_df from {output_file_path_final_all}")
    except FileNotFoundError:
        raise ValueError(f"Required file '{output_file_path_final_all}' for t-test not found. Please ensure it has been saved.")
    except Exception as e:
        raise ValueError(f"Error loading full_predictions_df for t-test: {e}")

# Ensure observed_flow_val and hybrid_predictions are extracted from full_predictions_df
# It's safer to re-extract these if full_predictions_df was just loaded or redefined.
if 'Observed Flow' in full_predictions_df.columns and \
   'QSWATPLUS Predictions' in full_predictions_df.columns and \
   'Overall Hybrid Predictions' in full_predictions_df.columns:
    observed_flow_val = full_predictions_df['Observed Flow']
    qswatplus_simulated_val = full_predictions_df['QSWATPLUS Predictions']
    hybrid_predictions = full_predictions_df['Overall Hybrid Predictions']
else:
    raise ValueError("Required columns for t-test (Observed Flow, QSWATPLUS Predictions, Overall Hybrid Predictions) not available in full_predictions_df.")

# Calculate absolute residuals for QSWATPLUS
abs_residuals_qswatplus = np.abs(observed_flow_val - qswatplus_simulated_val)

# Calculate absolute residuals for Hybrid Model
abs_residuals_hybrid = np.abs(observed_flow_val - hybrid_predictions)

# Perform a paired t-test
# We use a 'less' alternative hypothesis to test if Hybrid residuals are significantly smaller
# This assumes abs_residuals_qswatplus is sample A and abs_residuals_hybrid is sample B
# and we are testing if mean(A) > mean(B)

# The t-test assumes normality of the *differences* between paired samples.
# It's also sensitive to outliers. However, for a robust comparison, it's a common approach.

t_statistic, p_value = stats.ttest_rel(abs_residuals_qswatplus, abs_residuals_hybrid, alternative='greater')

print("\n--- Paired t-test Results (Absolute Residuals) ---")
print(f"QSWATPLUS Mean Absolute Residual: {abs_residuals_qswatplus.mean():.3f}")
print(f"Hybrid Model Mean Absolute Residual: {abs_residuals_hybrid.mean():.3f}")
print(f"\nTest Statistic (t): {t_statistic:.3f}")
print(f"P-value: {p_value:.4f}")

alpha = 0.05
if p_value < alpha:
    print(f"\nSince p-value ({p_value:.4f}) < alpha ({alpha}), we reject the null hypothesis.")
    print("Conclusion: The Hybrid Model's absolute residuals are significantly smaller than QSWATPLUS's absolute residuals.")
    print("This indicates a statistically significant improvement in performance for the Hybrid Model.")
else:
    print(f"\nSince p-value ({p_value:.4f}) >= alpha ({alpha}), we fail to reject the null hypothesis.")
    print("Conclusion: There is no statistically significant difference or improvement based on this test.")

