import ee
# Define the climate variables to extract and their corresponding GEE band names
# These are common variables in the GDDP-CMIP6 dataset.
# Note: GDDP-CMIP6 data is daily and usually at 0.25 degree resolution.
# Units: pr (kg m-2 s-1), tasmax/tasmin (K), sfcWind (m s-1), huss (1), rsds (W m-2)
climate_variables_mapping = {
    'pr': 'precipitation_flux_kg_m2_s',
    'tasmax': 'temperature_air_max_K',
    'tasmin': 'temperature_air_min_K',
    'sfcWind': 'surface_wind_speed_m_s',
    'huss': 'specific_humidity_1',
    'rsds': 'surface_downwelling_shortwave_radiation_W_m2'
}

def extract_data_at_stations(image):
    # Get the date of the image
    date = image.date().format('YYYY-MM-dd')

    selected_bands = []
    # Get band names as an ee.List (server-side)
    image_band_names = image.bandNames()

    for gee_band, readable_name in climate_variables_mapping.items():
        # Check if band exists using server-side operation ee.List.contains()
        if image_band_names.contains(gee_band):
            selected_bands.append(image.select(gee_band).rename(readable_name))

    # If no bands are selected, return an empty FeatureCollection to avoid issues with flatten()
    if not selected_bands:
        return ee.FeatureCollection([])

    # Combine selected bands into a single image (using first if only one, or mean if desired for multiple)
    # The original code had .mean() here, which implies it expects multiple selected bands to be combined.
    # If only one band is selected, it can be directly converted.
    combined_image = ee.Image(selected_bands).mean() if len(selected_bands) > 1 else ee.Image(selected_bands[0])

    # Reduce the image (extract value) at each station point
    reduced_data = combined_image.reduceRegions(
        collection=stations_ee,
        reducer=ee.Reducer.mean(), # Take the mean value within the pixel for each point
        scale=11132 # GDDP-CMIP6 resolution is 0.25 degrees, roughly 28km. Scale should match or be larger.
    )

    # Map a function to add date and station ID to each feature
    def add_date_and_id(feature):
        return feature.set({'Date': date, 'station_id': feature.get('station_id'), 'station_name': feature.get('station_name')})

    return reduced_data.map(add_date_and_id)

