def calculate_relative_error(observed, predicted):
    # Avoid division by zero by replacing 0 in observed with NaN
    observed_safe = observed.replace(0, np.nan)
    relative_err = np.abs(observed - predicted) / observed_safe * 100
    return relative_err

# Create a DataFrame to hold observed flow, predictions, and relative errors
