"""### Prepare CMIP6 Data for Forecasting

To use the trained models for future forecasting, we need to preprocess the CMIP6 climate data (CanESM5, ssp585, ssp245) in the same way as the historical data. This involves:

1.  **Combining** the individual scenario/period DataFrames into one.
2.  **Converting** the 'date' column to datetime objects.
3.  **Renaming** columns to match the features used during model training.
4.  **Applying** the same feature engineering steps (lagged features, time-based features, rolling window statistics).
"""

import pandas as pd
import numpy as np

# Combine all loaded CMIP6 dataframes into a single DataFrame
future_climate_df_list = [
    CanESM5_ssp585_Near, CanESM5_ssp585_Mid,
    CanESM5_ssp245_Near, CanESM5_ssp245_Mid
]

# Add scenario and period identifiers before concatenating
CanESM5_ssp585_Near['scenario'] = 'ssp585'
CanESM5_ssp585_Near['period'] = 'Near'
CanESM5_ssp585_Mid['scenario'] = 'ssp585'
CanESM5_ssp585_Mid['period'] = 'Mid'
CanESM5_ssp245_Near['scenario'] = 'ssp245'
CanESM5_ssp245_Near['period'] = 'Near'
CanESM5_ssp245_Mid['scenario'] = 'ssp245'
CanESM5_ssp245_Mid['period'] = 'Mid'

future_climate_df = pd.concat(future_climate_df_list, ignore_index=True)

# Convert 'date' column to datetime
future_climate_df['date'] = pd.to_datetime(future_climate_df['date'], errors='coerce')

# Drop rows where 'date' could not be parsed
future_climate_df.dropna(subset=['date'], inplace=True)

# Rename columns for consistency with historical data features
# Mapping CMIP6 output names to model feature names
# Removed 'wind_ms', 'hum_frac', 'swrad_mjm2' as they are not present in the CMIP6 data files.
column_rename_map = {
    'p_mm': 'avg_pcp',
    'tmin_c': 'avg_tmin',
    'tmean_c': 'avg_tmean', # Keep for potential use, though not directly in original features
    'tmax_c': 'avg_tmax'
}

future_climate_df.rename(columns=column_rename_map, inplace=True)

# Sort by date for correct lagging operations
future_climate_df = future_climate_df.sort_values(by=['scenario', 'period', 'date']).reset_index(drop=True)

print("--- Head of Combined Future Climate Data ---")
display(future_climate_df.head())
print("--- Info of Combined Future Climate Data ---")
future_climate_df.info()

"""### Feature Engineering for Future Climate Data

Now, we apply the same feature engineering steps to the combined future climate data that were used for the historical data (`df_ml`). This is critical to ensure that the input features for the trained models are consistent with what they were trained on.

We will create:

*   **Time-based features:** `year`, `month`, `day_of_year`, `day_of_week`, `week_of_year`.
*   **Rolling window statistics:** `rolling_avg_pcp_7d`.
"""

# Create a copy to work with for feature engineering
df_future_ml = future_climate_df.copy()

# --- Create Time-based Features ---
df_future_ml['year'] = df_future_ml['date'].dt.year
df_future_ml['month'] = df_future_ml['date'].dt.month
df_future_ml['day_of_year'] = df_future_ml['date'].dt.dayofyear
df_future_ml['day_of_week'] = df_future_ml['date'].dt.dayofweek # Monday=0, Sunday=6
df_future_ml['week_of_year'] = df_future_ml['date'].dt.isocalendar().week.astype(int)

# --- Create Rolling Window Statistics ---
# Note: Rolling window statistics need to be calculated carefully for each scenario/period group
# to avoid data leakage across different future projections.

df_future_ml['rolling_avg_pcp_7d'] = df_future_ml.groupby(['scenario', 'period'])['avg_pcp'].transform(lambda x: x.rolling(window=7, min_periods=1).mean())

# Lagged features (simulated_flow and observed_flow_lag1, etc.) cannot be directly created here
# as these are the values we are trying to predict or are historical. The models will use
# the climate features to predict 'observed_flow'. We'll need to decide how to handle
# 'simulated_flow' and 'observed_flow_lag1' for prediction - for now, they will be NaN.
# When predicting iteratively, the model's own previous prediction can be fed back as 'observed_flow_lag1' and 'simulated_flow_lag1'.

# For initial prediction without iterative feedback, we can use 0 or mean for lagged flow features.
# However, it's more common to have 'simulated_flow' (QSWATPLUS) and 'observed_flow_lag1' from the *start* of the prediction period
# which would be the end of the historical data.
# For now, let's keep them as NaN and address during prediction phase.

# The current models were trained on X which included 'simulated_flow' and lagged 'observed_flow'.
# For future prediction, 'simulated_flow' would be the QSWATPLUS prediction for the future.
# 'observed_flow_lag1' would be the actual observed flow from the *previous day*, which won't exist for future dates.
# For a true forecast, these would need iterative predictions or a different model setup.
# For now, let's create placeholder columns, and they will be filled with appropriate values (e.g., 0) or
# handled when calling predict depending on the model's feature expectation.

# Creating placeholder columns as models expect these features
# Assign dummy values (e.g., 0) or handle them as part of the prediction function
# 'simulated_flow' in future data means future QSWATPLUS output, which is not available in these CMIP6 files directly.
# We will use 'simulated_flow' from a separate future QSWATPLUS run if available, or assume a constant baseline/0.
# For this step, we'll create them as NaN as they represent model outputs or actual observations.

df_future_ml['simulated_flow'] = np.nan
df_future_ml['observed_flow_lag1'] = np.nan
df_future_ml['simulated_flow_lag1'] = np.nan
df_future_ml['avg_pcp_lag1'] = df_future_ml.groupby(['scenario', 'period'])['avg_pcp'].transform(lambda x: x.shift(1))
df_future_ml['observed_flow_lag7'] = np.nan
df_future_ml['avg_pcp_lag7'] = df_future_ml.groupby(['scenario', 'period'])['avg_pcp'].transform(lambda x: x.shift(7))
df_future_ml['rolling_avg_observed_flow_7d'] = np.nan

# Drop rows with NaN values resulting from initial lags for each group
# This might remove the first few days of each scenario/period, which is expected for lagged features.
df_future_ml.dropna(subset=['avg_pcp_lag1', 'avg_pcp_lag7', 'rolling_avg_pcp_7d'], inplace=True)

print("--- Head of Feature-Engineered Future Climate Data --- ")
display(df_future_ml.head())
print("--- Info of Feature-Engineered Future Climate Data --- ")
df_future_ml.info()

# 1. Extract historical initialization values from df_ml
last_historical_row = df_ml.iloc[-1]
initial_observed_flow = last_historical_row['observed_flow']
initial_simulated_flow = last_historical_row['simulated_flow']
initial_avg_pcp = last_historical_row['avg_pcp']
initial_rolling_avg_pcp_7d = last_historical_row['rolling_avg_pcp_7d']
initial_rolling_avg_observed_flow_7d = last_historical_row['rolling_avg_observed_flow_7d']

# Get the last 7 observed flows for initializing the rolling window
initial_observed_flow_lag_series = df_ml['observed_flow'].iloc[-7:]
initial_observed_flow_lag7 = df_ml['observed_flow'].iloc[-7] # Direct 7-day lag
historical_simulated_flow_mean = df_ml['simulated_flow'].mean()

# Get mean values for the missing climate features from the training data
mean_avg_slr = X_train['avg_slr'].mean()
mean_avg_wnd = X_train['avg_wnd'].mean()
mean_avg_hmd = X_train['avg_hmd'].mean()

# Define the features that the models expect as input (must match X_train columns)
ml_features = [
    'simulated_flow', 'avg_pcp', 'avg_tmax', 'avg_tmin', 'avg_slr', 'avg_wnd', 'avg_hmd',
    'observed_flow_lag1', 'simulated_flow_lag1', 'avg_pcp_lag1',
    'observed_flow_lag7', 'avg_pcp_lag7',
    'year', 'month', 'day_of_year', 'day_of_week', 'week_of_year',
    'rolling_avg_pcp_7d', 'rolling_avg_observed_flow_7d'
]

# Create a copy of the feature-engineered future climate data for predictions
df_future_predictions = df_future_ml.copy()

# Initialize columns to store predictions
df_future_predictions['RF_predictions'] = np.nan
df_future_predictions['XGB_predictions'] = np.nan
df_future_predictions['LightGBM_predictions'] = np.nan
df_future_predictions['LSTM_predictions'] = np.nan
df_future_predictions['Hybrid_predictions'] = np.nan
df_future_predictions['BMA_predictions'] = np.nan

# Store individual hybrid model predictions as well
df_future_predictions['Hybrid_QSWATPLUS_RF_predictions'] = np.nan
df_future_predictions['Hybrid_QSWATPLUS_XGB_predictions'] = np.nan
df_future_predictions['Hybrid_QSWATPLUS_LGBM_predictions'] = np.nan
df_future_predictions['Hybrid_QSWATPLUS_LSTM_predictions'] = np.nan


# Group by scenario and period to process each future projection independently
grouped_future_data = df_future_predictions.groupby(['scenario', 'period'])

all_predictions_list = []

print("Starting future streamflow forecasting...")

for (scenario, period), group_df in grouped_future_data:
    print(f"  Forecasting for Scenario: {scenario}, Period: {period} ({len(group_df)} days)")

    # Fill missing climate features that were in X_train but not in CMIP6 data
    group_df['avg_slr'] = mean_avg_slr
    group_df['avg_wnd'] = mean_avg_wnd
    group_df['avg_hmd'] = mean_avg_hmd

    # Use a copy to avoid SettingWithCopyWarning if group_df is a view
    group_predictions = group_df.copy()

    # Fill the 'simulated_flow' column with the historical mean for all future days in this group
    group_predictions['simulated_flow'] = historical_simulated_flow_mean

    # Initialize dynamic lagged features for the start of each new scenario/period
    # For the first day of each future projection, these are based on the end of historical data
    # or a reasonable baseline (e.g., historical mean for QSWATPLUS_simulated_flow if not available)
    current_observed_flow_lag1 = initial_observed_flow
    current_simulated_flow_lag1 = initial_simulated_flow # This is historical QSWATPLUS output
    current_avg_pcp_lag1 = initial_avg_pcp
    current_observed_flow_lag7 = initial_observed_flow_lag7 # The 7-day lag value

    # Rolling 7-day window for observed flow - start with last 7 historical values
    # For future days, this will be updated with model's own predictions
    rolling_observed_flow_window = list(initial_observed_flow_lag_series.values)

    for idx, row in group_df.iterrows():
        # Prepare the feature vector for the current day
        # Select features based on ml_features list to ensure correct order and columns
        X_day = row[ml_features].copy()

        # Update dynamic features
        # The 'simulated_flow' column in X_day is current_simulated_flow_from_future_qswatplus.
        # If no future QSWATPLUS data provided, we have to make an assumption.
        # Let's use the historical mean of QSWATPLUS simulated flow as a constant for this feature
        # for all future predictions, as no future QSWATPLUS runs are available.
        X_day['simulated_flow'] = historical_simulated_flow_mean # Assume constant QSWATPLUS output if not provided

        X_day['observed_flow_lag1'] = current_observed_flow_lag1
        X_day['simulated_flow_lag1'] = current_simulated_flow_lag1
        X_day['avg_pcp_lag1'] = row['avg_pcp_lag1'] # This is already calculated in df_future_ml

        # Recalculate observed_flow_lag7 based on rolling_observed_flow_window
        if len(rolling_observed_flow_window) >= 7:
            X_day['observed_flow_lag7'] = rolling_observed_flow_window[-7]
        else:
            X_day['observed_flow_lag7'] = current_observed_flow_lag7 # Fallback for first few days if window is not full

        # Recalculate rolling_avg_observed_flow_7d based on rolling_observed_flow_window
        X_day['rolling_avg_observed_flow_7d'] = np.mean(rolling_observed_flow_window[-7:])

        # Reshape for a single prediction (1 sample, N features)
        # Ensure the order of columns in X_day_df matches ml_features for consistency
        X_day_df = pd.DataFrame([X_day.values], columns=ml_features)

        # --- Make predictions with individual base models ---
        rf_pred = rf_model.predict(X_day_df)[0]
        xgb_pred = xgb_model.predict(X_day_df)[0]
        lgbm_pred = lgbm_model.predict(X_day_df)[0]

        # LSTM requires scaled and reshaped input
        X_day_scaled = scaler.transform(X_day_df)
        X_day_lstm = X_day_scaled.reshape(1, 1, X_day_scaled.shape[1])
        lstm_pred = lstm_model.predict(X_day_lstm, verbose=0)[0][0]

        # Ensure predictions are non-negative
        rf_pred = max(0, rf_pred)
        xgb_pred = max(0, xgb_pred)
        lgbm_pred = max(0, lgbm_pred)
        lstm_pred = max(0, lstm_pred)

        # Store base model predictions
        group_predictions.loc[idx, 'RF_predictions'] = rf_pred
        group_predictions.loc[idx, 'XGB_predictions'] = xgb_pred
        group_predictions.loc[idx, 'LightGBM_predictions'] = lgbm_pred
        group_predictions.loc[idx, 'LSTM_predictions'] = lstm_pred

        # Update dynamic features for the next day
        current_observed_flow_lag1 = rf_pred # Using RF prediction as the new 'observed_flow_lag1' for simplicity
        current_simulated_flow_lag1 = historical_simulated_flow_mean # Keep constant if no future QSWATPLUS
        # Update rolling window
        rolling_observed_flow_window.append(rf_pred) # Add new prediction
        if len(rolling_observed_flow_window) > 7:
            rolling_observed_flow_window.pop(0) # Remove oldest prediction

    # --- After base models predict for the entire group, calculate Hybrid and BMA predictions ---
    # Create input for meta-learner for this group
    X_meta_future = pd.DataFrame({
        'QSWATPLUS_Pred': group_predictions['simulated_flow'].values, # Using the imputed simulated_flow
        'RF_Pred': group_predictions['RF_predictions'].values,
        'XGB_Pred': group_predictions['XGB_predictions'].values,
        'LightGBM_Pred': group_predictions['LightGBM_predictions'].values,
        'LSTM_Pred': group_predictions['LSTM_predictions'].values
    })
    # Predict with overall Hybrid Model
    hybrid_predictions_group = meta_model.predict(X_meta_future)
    group_predictions['Hybrid_predictions'] = np.maximum(0, hybrid_predictions_group)

    # Predict with BMA Model
    bma_predictions_group = np.average(X_meta_future.values, axis=1, weights=bma_weights)
    group_predictions['BMA_predictions'] = np.maximum(0, bma_predictions_group)

    # Individual QSWATPLUS+ML hybrids
    # Hybrid_QSWATPLUS_RF
    X_meta_rf_future = pd.DataFrame({'QSWATPLUS_Pred': group_predictions['simulated_flow'].values, 'RF_Pred': group_predictions['RF_predictions'].values})
    hybrid_rf_predictions_group = meta_model_rf.predict(X_meta_rf_future)
    group_predictions['Hybrid_QSWATPLUS_RF_predictions'] = np.maximum(0, hybrid_rf_predictions_group)

    # Hybrid_QSWATPLUS_XGB
    X_meta_xgb_future = pd.DataFrame({'QSWATPLUS_Pred': group_predictions['simulated_flow'].values, 'XGB_Pred': group_predictions['XGB_predictions'].values})
    hybrid_xgb_predictions_group = meta_model_xgb.predict(X_meta_xgb_future)
    group_predictions['Hybrid_QSWATPLUS_XGB_predictions'] = np.maximum(0, hybrid_xgb_predictions_group)

    # Hybrid_QSWATPLUS_LGBM
    X_meta_lgbm_future = pd.DataFrame({'QSWATPLUS_Pred': group_predictions['simulated_flow'].values, 'LightGBM_Pred': group_predictions['LightGBM_predictions'].values})
    hybrid_lgbm_predictions_group = meta_model_lgbm.predict(X_meta_lgbm_future)
    group_predictions['Hybrid_QSWATPLUS_LGBM_predictions'] = np.maximum(0, hybrid_lgbm_predictions_group)

    # Hybrid_QSWATPLUS_LSTM
    X_meta_lstm_future = pd.DataFrame({'QSWATPLUS_Pred': group_predictions['simulated_flow'].values, 'LSTM_Pred': group_predictions['LSTM_predictions'].values})
    hybrid_lstm_predictions_group = meta_model_lstm.predict(X_meta_lstm_future)
    group_predictions['Hybrid_QSWATPLUS_LSTM_predictions'] = np.maximum(0, hybrid_lstm_predictions_group)


    all_predictions_list.append(group_predictions)

# Concatenate all predicted groups back into a single DataFrame
final_future_predictions_df = pd.concat(all_predictions_list, ignore_index=True)

print("\n--- Head of Future Streamflow Predictions ---")
display(final_future_predictions_df.head())

print("\n--- Info of Future Streamflow Predictions ---")
final_future_predictions_df.info()

# Save the predictions to CSV
output_predictions_path = os.path.join(drive_path, 'future_streamflow_predictions_CMIP6.csv')
final_future_predictions_df.to_csv(output_predictions_path, index=False)
