import pandas as pd
import numpy as np
import pymannkendall as mk
import os

drive_path = '/content/drive/MyDrive/GEE' # Ensure this path is correct
output_predictions_path = os.path.join(drive_path, 'future_streamflow_predictions_CMIP6.csv')

# Load the future streamflow predictions
try:
    final_future_predictions_df = pd.read_csv(output_predictions_path)
    final_future_predictions_df['date'] = pd.to_datetime(final_future_predictions_df['date'])
    final_future_predictions_df = final_future_predictions_df.set_index('date').sort_index()
    print(f"Successfully loaded future streamflow predictions from: {output_predictions_path}")
except FileNotFoundError:
    print(f"Error: Future streamflow predictions file not found at {output_predictions_path}")
    final_future_predictions_df = pd.DataFrame() # Create empty DataFrame to prevent errors
except Exception as e:
    print(f"An error occurred while loading future streamflow predictions: {e}")
    final_future_predictions_df = pd.DataFrame()


if not final_future_predictions_df.empty:
    # Define the columns that contain the flow predictions
    prediction_cols_for_mk = [
        'RF_predictions',
        'XGB_predictions',
        'LightGBM_predictions',
        'LSTM_predictions',
        'Hybrid_predictions',
        'BMA_predictions',
        'Hybrid_QSWATPLUS_RF_predictions',
        'Hybrid_QSWATPLUS_XGB_predictions',
        'Hybrid_QSWATPLUS_LGBM_predictions',
        'Hybrid_QSWATPLUS_LSTM_predictions'
    ]

    results = []

    # Group by scenario and period
    grouped_data = final_future_predictions_df.groupby(['scenario', 'period'])

    for (scenario, period), group_df in grouped_data:
        print(f"\n--- Analyzing trends for Scenario: {scenario}, Period: {period} ---")

        # Loop through each prediction column
        for col in prediction_cols_for_mk:
            if col in group_df.columns:
                series = group_df[col].dropna() # Drop NaNs before analysis

                if series.empty:
                    print(f"Warning: Skipping {col} in {scenario}/{period} due to insufficient data.")
                    continue

                # --- Daily Trend ---
                daily_mk = mk.original_test(series)
                results.append({
                    'Scenario': scenario,
                    'Period': period,
                    'Model': col,
                    'Time Scale': 'Daily',
                    'Z-statistic': daily_mk.z,
                    "Sen's Slope": daily_mk.slope,
                    'P-value': daily_mk.p,
                    'Trend': daily_mk.trend
                })

                # --- Monthly Average Trend ---
                monthly_avg_series = series.resample('ME').mean().dropna()
                if not monthly_avg_series.empty:
                    monthly_mk = mk.original_test(monthly_avg_series)
                    results.append({
                        'Scenario': scenario,
                        'Period': period,
                        'Model': col,
                        'Time Scale': 'Monthly Average',
                        'Z-statistic': monthly_mk.z,
                        "Sen's Slope": monthly_mk.slope,
                        'P-value': monthly_mk.p,
                        'Trend': monthly_mk.trend
                    })
                else:
                    print(f"Warning: No valid data for {col} Monthly Average trend test in {scenario}/{period}.")

                # --- Annually Average Trend ---
                annually_avg_series = series.resample('YE').mean().dropna()
                if not annually_avg_series.empty:
                    annually_mk = mk.original_test(annually_avg_series)
                    results.append({
                        'Scenario': scenario,
                        'Period': period,
                        'Model': col,
                        'Time Scale': 'Annually Average',
                        'Z-statistic': annually_mk.z,
                        "Sen's Slope": annually_mk.slope,
                        'P-value': annually_mk.p,
                        'Trend': annually_mk.trend
                    })
                else:
                    print(f"Warning: No valid data for {col} Annually Average trend test in {scenario}/{period}.")

                # --- Seasonal Trend (12-month period) ---
                # Ensure the series has enough data points for seasonal test
                if len(series) >= 2 * 12: # At least two full years needed for a reasonable seasonal test
                    seasonal_mk = mk.seasonal_test(series, period=12)
                    results.append({
                        'Scenario': scenario,
                        'Period': period,
                        'Model': col,
                        'Time Scale': 'Seasonal (12-month period)',
                        'Z-statistic': seasonal_mk.z,
                        "Sen's Slope": seasonal_mk.slope,
                        'P-value': seasonal_mk.p,
                        'Trend': seasonal_mk.trend
                    })
                else:
                    print(f"Warning: Not enough data for seasonal trend test for {col} in {scenario}/{period}.")

    # Create DataFrame from results
    future_mk_summary_df = pd.DataFrame(results)

    print("\n--- Future Streamflow Mann-Kendall and Sen's Slope Trend Analysis Summary ---")
    display(future_mk_summary_df.round(4))

    # Optionally save the summary to CSV
    output_mk_summary_path = os.path.join(drive_path, 'future_streamflow_mann_kendall_summary.csv')
    future_mk_summary_df.to_csv(output_mk_summary_path, index=False)
    print(f"Mann-Kendall trend summary table for future predictions saved to: {output_mk_summary_path}")
else:
    print("Cannot perform trend analysis: final_future_predictions_df is empty.")

