df_future_predictions['Hybrid_QSWATPLUS_LSTM_predictions'] = np.nan


# Group by scenario and period to process each future projection independently
grouped_future_data = df_future_predictions.groupby(['scenario', 'period'])

all_predictions_list = []

print("Starting future streamflow forecasting...")

for (scenario, period), group_df in grouped_future_data:
    print(f"  Forecasting for Scenario: {scenario}, Period: {period} ({len(group_df)} days)")

    # Fill missing climate features that were in X_train but not in CMIP6 data
    group_df['avg_slr'] = mean_avg_slr
    group_df['avg_wnd'] = mean_avg_wnd
    group_df['avg_hmd'] = mean_avg_hmd

    # Use a copy to avoid SettingWithCopyWarning if group_df is a view
    group_predictions = group_df.copy()

    # Fill the 'simulated_flow' column with the historical mean for all future days in this group
    group_predictions['simulated_flow'] = historical_simulated_flow_mean

    # Initialize dynamic lagged features for the start of each new scenario/period
    # For the first day of each future projection, these are based on the end of historical data
    # or a reasonable baseline (e.g., historical mean for QSWATPLUS_simulated_flow if not available)
    current_observed_flow_lag1 = initial_observed_flow
    current_simulated_flow_lag1 = initial_simulated_flow # This is historical QSWATPLUS output
    current_avg_pcp_lag1 = initial_avg_pcp
    current_observed_flow_lag7 = initial_observed_flow_lag7 # The 7-day lag value

    # Rolling 7-day window for observed flow - start with last 7 historical values
    # For future days, this will be updated with model's own predictions
    rolling_observed_flow_window = list(initial_observed_flow_lag_series.values)

    for idx, row in group_df.iterrows():
        # Prepare the feature vector for the current day
        # Select features based on ml_features list to ensure correct order and columns
        X_day = row[ml_features].copy()

        # Update dynamic features
        # The 'simulated_flow' column in X_day is current_simulated_flow_from_future_qswatplus.
        # If no future QSWATPLUS data provided, we have to make an assumption.
        # Let's use the historical mean of QSWATPLUS simulated flow as a constant for this feature
        # for all future predictions, as no future QSWATPLUS runs are available.
        X_day['simulated_flow'] = historical_simulated_flow_mean # Assume constant QSWATPLUS output if not provided

        X_day['observed_flow_lag1'] = current_observed_flow_lag1
        X_day['simulated_flow_lag1'] = current_simulated_flow_lag1
        X_day['avg_pcp_lag1'] = row['avg_pcp_lag1'] # This is already calculated in df_future_ml

        # Recalculate observed_flow_lag7 based on rolling_observed_flow_window
        if len(rolling_observed_flow_window) >= 7:
            X_day['observed_flow_lag7'] = rolling_observed_flow_window[-7]
        else:
            X_day['observed_flow_lag7'] = current_observed_flow_lag7 # Fallback for first few days if window is not full

        # Recalculate rolling_avg_observed_flow_7d based on rolling_observed_flow_window
        X_day['rolling_avg_observed_flow_7d'] = np.mean(rolling_observed_flow_window[-7:])

        # Reshape for a single prediction (1 sample, N features)
        # Ensure the order of columns in X_day_df matches ml_features for consistency
        X_day_df = pd.DataFrame([X_day.values], columns=ml_features)

        # --- Make predictions with individual base models ---
        rf_pred = rf_model.predict(X_day_df)[0]
        xgb_pred = xgb_model.predict(X_day_df)[0]
        lgbm_pred = lgbm_model.predict(X_day_df)[0]

        # LSTM requires scaled and reshaped input
        X_day_scaled = scaler.transform(X_day_df)
        X_day_lstm = X_day_scaled.reshape(1, 1, X_day_scaled.shape[1])
        lstm_pred = lstm_model.predict(X_day_lstm, verbose=0)[0][0]

        # Ensure predictions are non-negative
        rf_pred = max(0, rf_pred)
        xgb_pred = max(0, xgb_pred)
        lgbm_pred = max(0, lgbm_pred)
        lstm_pred = max(0, lstm_pred)

        # Store base model predictions
        group_predictions.loc[idx, 'RF_predictions'] = rf_pred
        group_predictions.loc[idx, 'XGB_predictions'] = xgb_pred
        group_predictions.loc[idx, 'LightGBM_predictions'] = lgbm_pred
        group_predictions.loc[idx, 'LSTM_predictions'] = lstm_pred

        # Update dynamic features for the next day
        current_observed_flow_lag1 = rf_pred # Using RF prediction as the new 'observed_flow_lag1' for simplicity
        current_simulated_flow_lag1 = historical_simulated_flow_mean # Keep constant if no future QSWATPLUS
        # Update rolling window
        rolling_observed_flow_window.append(rf_pred) # Add new prediction
        if len(rolling_observed_flow_window) > 7:
            rolling_observed_flow_window.pop(0) # Remove oldest prediction

    # --- After base models predict for the entire group, calculate Hybrid and BMA predictions ---
    # Create input for meta-learner for this group
    X_meta_future = pd.DataFrame({
        'QSWATPLUS_Pred': group_predictions['simulated_flow'].values, # Using the imputed simulated_flow
        'RF_Pred': group_predictions['RF_predictions'].values,
        'XGB_Pred': group_predictions['XGB_predictions'].values,
        'LightGBM_Pred': group_predictions['LightGBM_predictions'].values,
        'LSTM_Pred': group_predictions['LSTM_predictions'].values
    })
    # Predict with overall Hybrid Model
    hybrid_predictions_group = meta_model.predict(X_meta_future)
    group_predictions['Hybrid_predictions'] = np.maximum(0, hybrid_predictions_group)

    # Predict with BMA Model
    bma_predictions_group = np.average(X_meta_future.values, axis=1, weights=bma_weights)
    group_predictions['BMA_predictions'] = np.maximum(0, bma_predictions_group)

    # Individual QSWATPLUS+ML hybrids
    # Hybrid_QSWATPLUS_RF
    X_meta_rf_future = pd.DataFrame({'QSWATPLUS_Pred': group_predictions['simulated_flow'].values, 'RF_Pred': group_predictions['RF_predictions'].values})
    hybrid_rf_predictions_group = meta_model_rf.predict(X_meta_rf_future)
    group_predictions['Hybrid_QSWATPLUS_RF_predictions'] = np.maximum(0, hybrid_rf_predictions_group)

    # Hybrid_QSWATPLUS_XGB
    X_meta_xgb_future = pd.DataFrame({'QSWATPLUS_Pred': group_predictions['simulated_flow'].values, 'XGB_Pred': group_predictions['XGB_predictions'].values})
    hybrid_xgb_predictions_group = meta_model_xgb.predict(X_meta_xgb_future)
    group_predictions['Hybrid_QSWATPLUS_XGB_predictions'] = np.maximum(0, hybrid_xgb_predictions_group)

    # Hybrid_QSWATPLUS_LGBM
    X_meta_lgbm_future = pd.DataFrame({'QSWATPLUS_Pred': group_predictions['simulated_flow'].values, 'LightGBM_Pred': group_predictions['LightGBM_predictions'].values})
    hybrid_lgbm_predictions_group = meta_model_lgbm.predict(X_meta_lgbm_future)
    group_predictions['Hybrid_QSWATPLUS_LGBM_predictions'] = np.maximum(0, hybrid_lgbm_predictions_group)

    # Hybrid_QSWATPLUS_LSTM
    X_meta_lstm_future = pd.DataFrame({'QSWATPLUS_Pred': group_predictions['simulated_flow'].values, 'LSTM_Pred': group_predictions['LSTM_predictions'].values})
    hybrid_lstm_predictions_group = meta_model_lstm.predict(X_meta_lstm_future)
    group_predictions['Hybrid_QSWATPLUS_LSTM_predictions'] = np.maximum(0, hybrid_lstm_predictions_group)


