axes[1].set_title(f"Validation Period (R²={r2_test:.3f}, NSE={nse_test:.3f}, PBIAS={pbias_test:.3f}%)")
axes[1].set_xlabel("Observed Streamflow (m³/s)")
axes[1].set_ylabel("Predicted Streamflow (m³/s)")
